import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const root = fileURLToPath(new URL('..', import.meta.url));
const input = (path) => resolve(root, path);
const outfile = process.argv[2] ? resolve(process.argv[2]) : input('build/browser/agent-chat-browser.js');
const { version } = JSON.parse(await readFile(input('package.json'), 'utf8'));
const notice = [
  'Generated by AgentChat scripts/build-browser.mjs. Edit the upstream sources instead.',
  `AgentChat ${version} https://github.com/ryujt/AgentChat`,
  'Dependency licenses for this bundle follow.',
  ...await Promise.all(['LICENSE', 'node_modules/zod/LICENSE', 'node_modules/@noble/hashes/LICENSE']
    .map(async (path) => (await readFile(input(path), 'utf8')).trim())),
].join('\n\n');

await build({
  absWorkingDir: root,
  entryPoints: ['browser/monitor.ts'],
  outfile,
  bundle: true,
  platform: 'browser',
  format: 'esm',
  target: 'es2022',
  minify: true,
  alias: { 'node:crypto': input('browser/crypto.ts') },
  inject: [input('browser/bytes.ts')],
  define: { AGENT_CHAT_VERSION: JSON.stringify(version) },
  banner: { js: `/*!\n${notice}\n*/` },
  plugins: [{
    name: 'browser-websocket',
    setup(build) {
      build.onResolve({ filter: /^\.\/ws-socket\.js$/ }, ({ importer }) =>
        dirname(importer) === input('src/signaling-client') ? { path: input('browser/web-socket.ts') } : undefined);
    },
  }],
});
